###############################################################
#
# Project:
# An Affine Transformer--CNN--BiLSTM Framework with Adaptive
# Experience Replay for No-Arbitrage Macro-Financial
# Yield Curve Forecasting
#
# File:
# 16_statistical_financial_evaluation.R
#
# Purpose:
# Statistical evaluation of the financial decision strategies
# generated by 15_financial_decision.R.
#
# Main analyses:
#   1. Economic performance comparison
#   2. Cumulative net returns
#   3. Mean monthly returns
#   4. Volatility
#   5. Sharpe-like ratios
#   6. Maximum drawdown
#   7. Portfolio switching / turnover
#   8. Directional hit rate
#   9. Pairwise Diebold--Mariano tests (Newey-West NW)
#  10. Paired bootstrap confidence intervals
#  11. Model ranking
#
###############################################################


###############################################################
# 0. CLEAN SESSION
###############################################################

rm(list = ls())

options(
    stringsAsFactors = FALSE,
    scipen = 999
)

set.seed(20260914)

cat("\n")
cat("============================================================\n")
cat("16_STATISTICAL_FINANCIAL_EVALUATION.R\n")
cat("Statistical Evaluation of Portfolio Strategies\n")
cat("============================================================\n")
cat("\n")


###############################################################
# 1. PACKAGES
###############################################################

required_packages <- c(
    "dplyr",
    "tidyr",
    "ggplot2",
    "readr",
    "forecast",
    "sandwich"
)

for (pkg in required_packages) {
    if (!requireNamespace(pkg, quietly = TRUE)) {
        stop(paste0("Required package '", pkg, "' is not installed."))
    }
}

suppressPackageStartupMessages({
    library(dplyr)
    library(tidyr)
    library(ggplot2)
    library(readr)
    library(forecast)
    library(sandwich)
})


###############################################################
# 2. INPUT & OUTPUT FILE RESOLUTION
###############################################################

OUTPUT_DIR <- "16_Statistical_Financial_Evaluation"
if (!dir.exists(OUTPUT_DIR)) {
    dir.create(OUTPUT_DIR, recursive = TRUE, showWarnings = FALSE)
}

candidate_files <- c(
    "15_Financial_Decision_Results.RData",
    file.path("15_Financial_Decision", "15_Financial_Decision_Results.RData")
)

FINANCIAL_FILE <- candidate_files[file.exists(candidate_files)][1]

if (is.na(FINANCIAL_FILE) || !file.exists(FINANCIAL_FILE)) {
    stop("File not found: 15_Financial_Decision_Results.RData. Run 15_financial_decision.R first.")
}

OUTPUT_RDATA         <- file.path(OUTPUT_DIR, "16_Statistical_Financial_Evaluation.RData")
OUTPUT_SUMMARY_CSV   <- file.path(OUTPUT_DIR, "16_Financial_Model_Comparison.csv")
OUTPUT_DM_CSV        <- file.path(OUTPUT_DIR, "16_Financial_DM_Tests.csv")
OUTPUT_BOOTSTRAP_CSV <- file.path(OUTPUT_DIR, "16_Financial_Bootstrap_CI.csv")
OUTPUT_DETAIL_CSV    <- file.path(OUTPUT_DIR, "16_Financial_Evaluation_Detail.csv")


###############################################################
# 3. LOAD FINANCIAL DECISION RESULTS
###############################################################

load(FINANCIAL_FILE)
cat("Loaded: ", FINANCIAL_FILE, "\n", sep = "")

if (!exists("financial_decision_detail")) {
    stop("Object 'financial_decision_detail' was not found in ", FINANCIAL_FILE)
}

financial_decision_detail <- as.data.frame(financial_decision_detail)

cat("Observations: ", nrow(financial_decision_detail), "\n", sep = "")
cat("Models: ", length(unique(financial_decision_detail$Model)), "\n", sep = "")


###############################################################
# 4. HELPER FUNCTIONS
###############################################################

safe_mean <- function(x) {
    x <- x[is.finite(x)]
    if (length(x) == 0) return(NA_real_)
    mean(x)
}

safe_sd <- function(x) {
    x <- x[is.finite(x)]
    if (length(x) < 2) return(NA_real_)
    sd(x)
}

safe_sharpe <- function(x) {
    x <- x[is.finite(x)]
    if (length(x) < 2) return(NA_real_)
    s <- sd(x)
    if (!is.finite(s) || s <= 0) return(NA_real_)
    mean(x) / s
}

safe_cumulative_return <- function(x) {
    x <- x[is.finite(x)]
    if (length(x) == 0) return(NA_real_)
    prod(1 + x) - 1
}

safe_max_drawdown <- function(x) {
    x <- x[is.finite(x)]
    if (length(x) == 0) return(NA_real_)
    wealth <- cumprod(1 + x)
    running_max <- cummax(wealth)
    drawdown <- wealth / running_max - 1
    min(drawdown)
}

safe_hit_rate <- function(expected, realized) {
    keep <- is.finite(expected) & is.finite(realized)
    expected <- expected[keep]
    realized <- realized[keep]
    if (length(expected) == 0) return(NA_real_)
    mean(sign(expected) == sign(realized))
}


###############################################################
# 5. MODEL-LEVEL PERFORMANCE SUMMARIES
###############################################################

financial_model_summary <- financial_decision_detail %>%
    dplyr::group_by(Model) %>%
    dplyr::summarise(
        N                         = sum(is.finite(NetRealizedReturn)),
        MeanExpectedReturn        = safe_mean(SelectedExpectedReturn),
        MeanRealizedReturn        = safe_mean(SelectedRealizedReturn),
        MeanNetReturn             = safe_mean(NetRealizedReturn),
        SDNetReturn               = safe_sd(NetRealizedReturn),
        SharpeLike                = safe_sharpe(NetRealizedReturn),
        CumulativeGrossReturn     = safe_cumulative_return(SelectedRealizedReturn),
        CumulativeNetReturn       = safe_cumulative_return(NetRealizedReturn),
        MaximumDrawdown           = safe_max_drawdown(NetRealizedReturn),
        SwitchingRate             = safe_mean(PortfolioSwitch),
        NumberOfSwitches          = sum(PortfolioSwitch, na.rm = TRUE),
        DirectionalHitRate        = safe_hit_rate(SelectedExpectedReturn, SelectedRealizedReturn),
        ShortSelectionRate        = safe_mean(SelectedPortfolio == "Short"),
        IntermediateSelectionRate = safe_mean(SelectedPortfolio == "Intermediate"),
        LongSelectionRate         = safe_mean(SelectedPortfolio == "Long"),
        MeanTransactionCost       = safe_mean(TransactionCost),
        TotalTransactionCost      = sum(TransactionCost, na.rm = TRUE),
        .groups                   = "drop"
    ) %>%
    dplyr::arrange(dplyr::desc(CumulativeNetReturn))


###############################################################
# 6. PAIRWISE RETURN DIFFERENCES
###############################################################

model_names <- unique(financial_decision_detail$Model)

if (length(model_names) < 2) {
    stop("At least two models are required for pairwise comparison.")
}

pair_list <- list()
pair_counter <- 0

for (i in seq_len(length(model_names) - 1)) {
    for (j in (i + 1):length(model_names)) {
        m1 <- model_names[i]
        m2 <- model_names[j]

        d1 <- financial_decision_detail %>%
            dplyr::filter(Model == m1) %>%
            dplyr::select(TestIndex, Return_1 = NetRealizedReturn)

        d2 <- financial_decision_detail %>%
            dplyr::filter(Model == m2) %>%
            dplyr::select(TestIndex, Return_2 = NetRealizedReturn)

        comp <- dplyr::inner_join(d1, d2, by = "TestIndex") %>%
            dplyr::filter(is.finite(Return_1) & is.finite(Return_2))

        if (nrow(comp) == 0) next

        comp$Difference <- comp$Return_1 - comp$Return_2
        pair_counter <- pair_counter + 1
        pair_list[[pair_counter]] <- comp %>%
            dplyr::mutate(Model_1 = m1, Model_2 = m2) %>%
            dplyr::select(Model_1, Model_2, TestIndex, Return_1, Return_2, Difference)
    }
}

financial_return_differences <- dplyr::bind_rows(pair_list)


###############################################################
# 7. DIEBOLD--MARIANO TESTING
###############################################################

dm_results <- list()
dm_counter <- 0

pair_keys <- unique(financial_return_differences[, c("Model_1", "Model_2")])

for (i in seq_len(nrow(pair_keys))) {
    m1 <- pair_keys$Model_1[i]
    m2 <- pair_keys$Model_2[i]

    comp <- financial_return_differences %>%
        dplyr::filter(Model_1 == m1, Model_2 == m2)

    x <- comp$Return_1
    y <- comp$Return_2
    keep <- is.finite(x) & is.finite(y)
    x <- x[keep]
    y <- y[keep]

    if (length(x) < 10) next

    dm_obj <- tryCatch({
        forecast::dm.test(e1 = x, e2 = y, alternative = "two.sided", h = 1, power = 2)
    }, error = function(e) NULL)

    dm_counter <- dm_counter + 1

    if (is.null(dm_obj)) {
        dm_results[[dm_counter]] <- data.frame(
            Model_1 = m1, Model_2 = m2, N = length(x),
            DM = NA_real_, p_value = NA_real_, Alternative = "two.sided",
            stringsAsFactors = FALSE
        )
    } else {
        dm_results[[dm_counter]] <- data.frame(
            Model_1 = m1, Model_2 = m2, N = length(x),
            DM = as.numeric(dm_obj$statistic),
            p_value = as.numeric(dm_obj$p.value),
            Alternative = dm_obj$alternative,
            stringsAsFactors = FALSE
        )
    }
}

financial_DM_tests <- dplyr::bind_rows(dm_results)


###############################################################
# 8. PAIRED BOOTSTRAP CONFIDENCE INTERVALS
###############################################################

bootstrap_difference <- function(x, y, B = 5000, seed = 20260914) {
    keep <- is.finite(x) & is.finite(y)
    x <- x[keep]
    y <- y[keep]
    n <- length(x)

    if (n < 2) {
        return(data.frame(N = n, MeanDifference = NA_real_, CI_Lower = NA_real_, CI_Upper = NA_real_, P_Value = NA_real_))
    }

    diff_vec <- x - y
    observed <- mean(diff_vec)

    set.seed(seed)
    boot_vals <- numeric(B)
    for (b in seq_len(B)) {
        idx <- sample.int(n, size = n, replace = TRUE)
        boot_vals[b] <- mean(diff_vec[idx])
    }

    ci <- stats::quantile(boot_vals, probs = c(0.025, 0.975), na.rm = TRUE)
    p_val <- 2 * min(mean(boot_vals <= 0), mean(boot_vals >= 0))

    data.frame(
        N = n, MeanDifference = observed,
        CI_Lower = as.numeric(ci[1]), CI_Upper = as.numeric(ci[2]),
        P_Value = p_val
    )
}

bootstrap_results <- list()
bootstrap_counter <- 0

for (i in seq_len(nrow(pair_keys))) {
    m1 <- pair_keys$Model_1[i]
    m2 <- pair_keys$Model_2[i]

    comp <- financial_return_differences %>%
        dplyr::filter(Model_1 == m1, Model_2 == m2)

    res <- bootstrap_difference(comp$Return_1, comp$Return_2, B = 5000, seed = 20260914 + i)
    res$Model_1 <- m1
    res$Model_2 <- m2

    bootstrap_counter <- bootstrap_counter + 1
    bootstrap_results[[bootstrap_counter]] <- res %>% dplyr::select(Model_1, Model_2, dplyr::everything())
}

financial_bootstrap_CI <- dplyr::bind_rows(bootstrap_results)

financial_statistical_comparison <- dplyr::left_join(
    financial_DM_tests, financial_bootstrap_CI,
    by = c("Model_1", "Model_2", "N")
)


###############################################################
# 9. PAIRED RETURN SUMMARIES & RANKINGS
###############################################################

paired_return_summary <- financial_return_differences %>%
    dplyr::group_by(Model_1, Model_2) %>%
    dplyr::summarise(
        N                      = dplyr::n(),
        MeanDifference         = mean(Difference, na.rm = TRUE),
        MedianDifference       = median(Difference, na.rm = TRUE),
        SDDifference           = sd(Difference, na.rm = TRUE),
        PositiveDifferenceRate = mean(Difference > 0, na.rm = TRUE),
        .groups                = "drop"
    )

financial_model_summary <- financial_model_summary %>%
    dplyr::mutate(
        Rank_CumulativeReturn = rank(-CumulativeNetReturn, ties.method = "min"),
        Rank_Sharpe           = rank(-SharpeLike, ties.method = "min"),
        Rank_Drawdown         = rank(-MaximumDrawdown, ties.method = "min")
    )

financial_evaluation_detail <- financial_decision_detail


###############################################################
# 10. SAVE CSV & RDATA ARTIFACTS
###############################################################

readr::write_csv(financial_model_summary, OUTPUT_SUMMARY_CSV)
readr::write_csv(financial_statistical_comparison, OUTPUT_DM_CSV)
readr::write_csv(financial_bootstrap_CI, OUTPUT_BOOTSTRAP_CSV)
readr::write_csv(financial_evaluation_detail, OUTPUT_DETAIL_CSV)

save(
    financial_decision_detail,
    financial_model_summary,
    financial_return_differences,
    paired_return_summary,
    financial_DM_tests,
    financial_bootstrap_CI,
    financial_statistical_comparison,
    financial_evaluation_detail,
    file = OUTPUT_RDATA
)


###############################################################
# 11. CONSOLE OUTPUT
###############################################################

cat("\n============================================================\n")
cat("MODEL-LEVEL FINANCIAL PERFORMANCE\n")
cat("============================================================\n")
print(financial_model_summary)

cat("\n============================================================\n")
cat("DIEBOLD--MARIANO TESTS\n")
cat("============================================================\n")
