cat("\n============================================================\n")
cat("BOOTSTRAP CONFIDENCE INTERVALS\n")
cat("============================================================\n")
print(financial_bootstrap_CI)

cat("\n============================================================\n")
cat("MODEL RANKING\n")
cat("============================================================\n")
print(
    financial_model_summary %>%
        dplyr::select(
            Model, CumulativeNetReturn, SharpeLike, MaximumDrawdown,
            SwitchingRate, DirectionalHitRate, Rank_CumulativeReturn,
